# main.tf — Terraform configuration for a web application stack
# (HCL syntax rendered here as yaml-adjacent for readability)

terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
  backend "s3" {
    bucket         = "my-terraform-state-bucket"
    key            = "prod/main.tfstate"
    region         = "us-east-1"
    dynamodb_table = "terraform-lock"  # prevent concurrent applies
    encrypt        = true
  }
}

provider "aws" { region = var.aws_region }

# --- Variables (parameterize for dev/staging/prod reuse) ---
variable "aws_region" { default = "us-east-1" }
variable "instance_count" { default = 2 }
variable "env" { description = "deployment environment" }

# --- Resources ---
resource "aws_instance" "web" {
  count         = var.instance_count
  ami           = "ami-0c02fb55956c7d316"  # Amazon Linux 2023
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.private.id
  vpc_security_group_ids = [aws_security_group.web.id]
  tags = { Name = "web-${var.env}-${count.index}", Env = var.env }
}

# --- Output the load balancer DNS for the deployment pipeline ---
output "lb_dns" {
  value = aws_lb.main.dns_name
}
